#!/usr/bin/env node
// Generates src/data/attackTechniques.ts in backend/ and backend-serverless/,
// plus the frontend technique->tactic table (frontend/src/lib/attackTechniqueTactics.ts),
// from MITRE ATT&CK Enterprise (github.com/mitre/cti). Re-run when ATT&CK
// ships a new version, then commit both generated files.
// ATTACK_STIX_FILE=<path to enterprise-attack.json> reads a local copy instead
// of downloading master.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SOURCE = 'https://raw.githubusercontent.com/mitre/cti/master/enterprise-attack/enterprise-attack.json';
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const targets = ['backend/src/data/attackTechniques.ts', 'backend-serverless/src/data/attackTechniques.ts'];
const frontendTarget = 'frontend/src/lib/attackTechniqueTactics.ts';

let bundle;
if (process.env.ATTACK_STIX_FILE) {
  bundle = JSON.parse(readFileSync(process.env.ATTACK_STIX_FILE, 'utf8'));
} else {
  const res = await fetch(SOURCE);
  if (!res.ok) throw new Error(`Download failed: ${res.status} ${res.statusText}`);
  bundle = await res.json();
}

const byId = new Map(bundle.objects.map((o) => [o.id, o]));
const revokedBy = new Map(
  bundle.objects.filter((o) => o.type === 'relationship' && o.relationship_type === 'revoked-by').map((r) => [r.source_ref, r.target_ref]),
);
const attackId = (o) => (o.external_references ?? []).find((r) => r.source_name === 'mitre-attack')?.external_id;
const phasesOf = (o) => (o.kill_chain_phases ?? []).filter((p) => p.kill_chain_name === 'mitre-attack').map((p) => p.phase_name);

const techniques = {};
const revokedObjects = [];
for (const o of bundle.objects) {
  if (o.type !== 'attack-pattern' || o.x_mitre_deprecated) continue;
  const id = attackId(o);
  if (!id) continue;
  if (o.revoked) revokedObjects.push(o);
  else techniques[id] = { name: o.name, tactics: phasesOf(o) };
}
// Library tests still cite ids ATT&CK revoked and renumbered, so keep a revoked
// technique unless its id was reused by an active one. Its own phases win; the
// technique its revoked-by relationship points to is the fallback.
for (const o of revokedObjects) {
  const id = attackId(o);
  if (id in techniques) continue;
  let tactics = phasesOf(o);
  if (tactics.length === 0) {
    const replacement = byId.get(revokedBy.get(o.id));
    tactics = replacement ? phasesOf(replacement) : [];
  }
  techniques[id] = { name: o.name, tactics };
}

// Revoked id -> the active technique that replaced it (revoked-by, followed
// through chains). EDRs report the new ids while library tests may cite the old
// ones, so matching code treats the pair as one technique (data/techniqueAliases.ts).
// An id reused by an active technique keeps its active meaning and is not mapped.
const activeIds = new Set(
  bundle.objects.filter((o) => o.type === 'attack-pattern' && !o.revoked && !o.x_mitre_deprecated).map(attackId).filter(Boolean),
);
const revokedByIds = {};
for (const o of revokedObjects) {
  const id = attackId(o);
  if (activeIds.has(id)) continue;
  let target = byId.get(revokedBy.get(o.id));
  for (let hops = 0; target?.revoked && hops < 10; hops++) target = byId.get(revokedBy.get(target.id));
  const targetId = target && !target.revoked ? attackId(target) : undefined;
  if (targetId && targetId !== id && activeIds.has(targetId)) revokedByIds[id] = targetId;
}

const ids = Object.keys(techniques).sort();
const version = bundle.objects.find((o) => o.type === 'x-mitre-collection')?.x_mitre_version ?? 'unknown';
const body = ids.map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(techniques[id])},`).join('\n');
const revokedBody = Object.keys(revokedByIds).sort()
  .map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(revokedByIds[id])},`).join('\n');
const file = `// GENERATED by scripts/generate-attack-techniques.mjs from MITRE ATT&CK Enterprise ${version}.
// Do not edit by hand; re-run the script instead.

export interface AttackTechniqueInfo {
  name: string;
  /** Kebab-case tactic short names, e.g. 'credential-access'. */
  tactics: string[];
}

export const ATTACK_TECHNIQUES: Record<string, AttackTechniqueInfo> = {
${body}
};

export function techniqueInfo(id: string): AttackTechniqueInfo | null {
  return ATTACK_TECHNIQUES[id.toUpperCase()] ?? null;
}

/** Revoked technique id -> the active id that replaced it (MITRE revoked-by). */
export const ATTACK_TECHNIQUE_REVOKED_BY: Record<string, string> = {
${revokedBody}
};
`;

for (const target of targets) {
  mkdirSync(dirname(join(root, target)), { recursive: true });
  writeFileSync(join(root, target), file);
}
const tacticBody = ids
  .filter((id) => techniques[id].tactics.length > 0)
  .map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(techniques[id].tactics)},`)
  .join('\n');
const nameBody = ids.map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(techniques[id].name)},`).join('\n');
writeFileSync(
  join(root, frontendTarget),
  `// GENERATED by scripts/generate-attack-techniques.mjs from MITRE ATT&CK Enterprise (mitre/cti master).
// Do not edit by hand; re-run the script instead.
// Technique ID -> tactic slugs (match ENTERPRISE_TACTICS[].slug in mitreTactics.ts).
// Revoked IDs resolve as in the backend table (own phases, else the replacement's).
export const TECHNIQUE_TACTICS: Record<string, readonly string[]> = {
${tacticBody}
};

// Technique ID -> ATT&CK technique name (revoked IDs keep their own name).
export const TECHNIQUE_NAMES: Record<string, string> = {
${nameBody}
};
`,
);
console.log(`Wrote ${ids.length} techniques and ${Object.keys(revokedByIds).length} revoked-by ids (ATT&CK ${version}) to ${targets.join(', ')}`);
